1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.OwnerIdentity;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityDuplicateException;
8	
9	/**
10	 * The exact-identity duplicate-detection step of {@code POST /api/owners}. Runs after
11	 * {@link CheckOwnerHouseholdUnique} (so an undeclared second member of a household has already been
12	 * rejected) and before {@link SaveOwner}. Rejects the create with a 409 via
13	 * {@link OwnerIdentityDuplicateException} when the new owner's whole derived {@code identityKey} equals
14	 * an existing owner's.
15	 *
16	 * <p>This replaces the former separate telephone, email and household checks: all three are now
17	 * expressed through the one {@link OwnerIdentity} key. Because the normalized telephone is part of the
18	 * key, two members of the same household (same {@code householdId}) with different telephones have
19	 * different keys and are both allowed — only an exact full-key match is a duplicate. The new owner is
20	 * still unsaved, so it is not among the owners iterated here and cannot match itself.
21	 */
22	public class CheckOwnerIdentityUnique {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
25	            throws OwnerIdentityDuplicateException {
26	        String identityKey = OwnerIdentity.of(owner);
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (identityKey.equals(OwnerIdentity.of(existing))) {
29	                throw new OwnerIdentityDuplicateException(identityKey);
30	            }
31	        }
32	    }
33	}
